// Pure run predicates over the store's run slices. Several runs may be live
// on one cell; each owns the files under its run folder `_runs/<label>/`
// (the folder IS the lock — there is no lock table). Structural slices, so
// reactive selectors (s => cellHasLiveRun(s, id)) and getState() callers
// both type-check.

import type { RunRecord } from '@/lib/types';

// The run-folder root.
// GENERATED by frontend/scripts/sync_app_constants.py from api/run_folders.py; do not edit.
export const RUNS_PREFIX = '_runs';
// END GENERATED

/** Cell-relative POSIX normalization, pinned to the SDK's run-path fixture. */
export function normalizeRunPath(path: string): string {
    const parts: string[] = [];
    for (const segment of path.replace(/\\/g, '/').replace(/^\/+/, '').split('/')) {
        if (!segment || segment === '.') continue;
        if (segment === '..' && parts.length && parts[parts.length - 1] !== '..') parts.pop();
        else parts.push(segment);
    }
    return parts.join('/');
}

/** True for any path under `_runs/` (a live run's lock or a dead folder
 *  the host sweeps). */
export function isRunPath(path: string): boolean {
    const normalized = normalizeRunPath(path);
    return normalized === RUNS_PREFIX || normalized.startsWith(`${RUNS_PREFIX}/`);
}

/** The run label a `_runs/<label>/…` path belongs to, else null. */
export function runLabelOf(path: string): string | null {
    const normalized = normalizeRunPath(path);
    if (!normalized.startsWith(`${RUNS_PREFIX}/`)) return null;
    const label = normalized.slice(RUNS_PREFIX.length + 1).split('/')[0];
    return label || null;
}

/** A RunRecord from the server's run shape (the POST /runs answer, a
 *  run_started broadcast, a /runs/active row). `channel` is the channel
 *  UUID the run belongs to. */
export function runRecordFrom(info: {
    run_id: string;
    cell_id: string;
    runner_id: string | null;
    runner_name: string | null;
    label: string;
    folder: string;
    generator_name: string;
    surfaces?: RunRecord['surfaces'];
}, channel: string): RunRecord {
    return {
        runId: info.run_id,
        cellId: info.cell_id,
        channel,
        runnerId: info.runner_id ?? null,
        runnerName: info.runner_name ?? null,
        generatorName: info.generator_name ?? '',
        label: info.label,
        folder: info.folder,
        surfaces: info.surfaces,
    };
}

/** Whether `path` is a run card (`_runs/<label>/<label>.run`): the run's
 *  record, which the app never opens on the run's behalf. */
export function isRunCardPath(path: string): boolean {
    return isRunPath(path) && path.endsWith('.run');
}

/** The run card's path in a run folder (`_runs/<label>/<label>.run`). */
export function runCardPath(run: Pick<RunRecord, 'folder' | 'label'>): string {
    return `${run.folder}/${run.label}.run`;
}

export interface RunStateSlice {
    runs: Record<string, RunRecord>;
    stoppingRunIds: Set<string>;
}

/** Extends RunStateSlice with the live phase map. */
export interface BusyStateSlice extends RunStateSlice {
    runPhases: Record<string, { phase: string; message?: string }>;
}

export const AWAITING_INPUT_PHASE = 'awaiting_input';

/** An approval card (gen.ask) waits on the user mid-turn. The run stays
 *  busy — its turn resumes on the answer — and the host pauses its
 *  watchdog meanwhile. */
export const AWAITING_APPROVAL_PHASE = 'awaiting_approval';

/** The terminal phases — the run's final status mirrored onto its phase
 *  (api/process_manager/phases.py TERMINAL_PHASES). A run's live phase
 *  indicator tracks active phases only; the run's end is endRun's. */
const TERMINAL_PHASES: ReadonlySet<string> = new Set([
    'completed', 'failed', 'stopped', 'timed_out', 'interrupted',
]);

export function isTerminalPhase(phase: string): boolean {
    return TERMINAL_PHASES.has(phase);
}

const isLive = (s: RunStateSlice, runId: string): boolean =>
    Object.hasOwn(s.runs, runId);

/** The live runs on a cell (active or stopping), in start order. */
export function runsOnCell(s: RunStateSlice, cellId: string): RunRecord[] {
    const out: RunRecord[] = [];
    for (const run of Object.values(s.runs)) {
        if (run.cellId === cellId && isLive(s, run.runId)) out.push(run);
    }
    return out;
}

/** Any run is live on the cell. Hides the header's remove button and gates
 *  every structural action that would delete, move or copy the cell's
 *  files (remove cell/stack, collapse, expand). */
export function cellHasLiveRun(s: RunStateSlice, cellId: string): boolean {
    return runsOnCell(s, cellId).length > 0;
}

/** The live run whose folder holds `path` on this cell, else null. */
export function lockOwner(s: RunStateSlice, cellId: string, path: string | null | undefined): RunRecord | null {
    if (!path) return null;
    const label = runLabelOf(path);
    const normalized = normalizeRunPath(path);
    return runsOnCell(s, cellId).find(run =>
        (label !== null && run.label === label)
        || run.surfaces?.some(surface => surface.path === normalized)) ?? null;
}

/** The file that is the run's own UI, for the status view's Open button:
 *  its registered surface when the cell holds it, else the first file in
 *  its run folder (alphabetically) that is neither its run card nor a
 *  folder keeper; null when it has none. */
export function runUiPath(run: Pick<RunRecord, 'folder' | 'label' | 'surfaces'>, filePaths: readonly string[]): string | null {
    const present = new Set(filePaths);
    const surface = run.surfaces?.find(s => present.has(s.path));
    if (surface) return surface.path;
    const card = runCardPath(run);
    const inFolder = filePaths
        .filter(p => p.startsWith(`${run.folder}/`) && p !== card && !p.endsWith('/.collkeep'))
        .sort();
    return inFolder[0] ?? null;
}

export type DotStatus = 'awaiting_approval' | 'running' | 'spinning_up' | 'awaiting_input' | 'stopping';

const SPINNING_UP_PHASES: ReadonlySet<string> = new Set(['spinning_up', 'queued']);

/** The run's phase says it is still spinning up (queued counts). */
export function isSpinningUpPhase(phase: string | undefined): boolean {
    return phase !== undefined && SPINNING_UP_PHASES.has(phase);
}

/** The cell's run light, by precedence over its live runs: awaiting
 *  approval → busy running → spinning up → awaiting input → all stopping.
 *  Null when no run is live (the idle dot). A run with no phase yet counts
 *  as running. */
export function dotStatus(s: BusyStateSlice, cellId: string): DotStatus | null {
    const runs = runsOnCell(s, cellId);
    if (runs.length === 0) return null;
    const phases = runs
        .filter(run => !s.stoppingRunIds.has(run.runId))
        .map(run => s.runPhases[run.runId]?.phase);
    if (phases.length === 0) return 'stopping';
    if (phases.includes(AWAITING_APPROVAL_PHASE)) return 'awaiting_approval';
    if (phases.some(p => p === undefined || (p !== AWAITING_INPUT_PHASE && !isSpinningUpPhase(p)))) {
        return 'running';
    }
    if (phases.some(isSpinningUpPhase)) return 'spinning_up';
    return 'awaiting_input';
}
